/// One turn's input, every value by name.
#[derive(Debug, Clone, Default)]
pub struct Input {
    /// Each joint's angle, from its encoder, in motor order: left leg, right leg, waist, left arm, right arm.
    pub joints: Vec<f32>,
    /// Each joint's angular velocity, in motor order.
    pub joint_velocities: Vec<f32>,
    /// What the pelvis IMU and the robot's own state estimate give.
    pub imu: Vec<f32>,
    /// The board: the current card (the earliest whose window is still open) and the next. When no card is left, the start stance, a pose, ten seconds away, with no window.
    pub cards: Vec<f32>,
    /// The scoreboard and the music.
    pub dance: Vec<f32>,
}

impl Input {
    /// Read this turn's input; `None` if it isn't one.
    pub fn parse(bytes: &[u8]) -> Option<Self> {
        let mut reader = Reader::new(bytes, b'I')?;
        let input = Self {
            joints: reader.f32s(joints::LEN)?,
            joint_velocities: reader.f32s(joint_velocities::LEN)?,
            imu: reader.f32s(imu::LEN)?,
            cards: reader.f32s(cards::LEN)?,
            dance: reader.f32s(dance::LEN)?,
        };
        reader.end().then_some(input)
    }
}

/// One turn's output, every value by name. Every element must be inside
/// its bounds (`MIN`, `MAX`), or the whole output is no action.
#[derive(Debug, Clone)]
pub struct Output {
    /// Each joint's target angle, in motor order. The motors track it with the G1's published gains and torque limits.
    pub targets: Vec<f32>,
}

impl Output {
    /// Every element at the middle of its bounds: always valid.
    pub fn midpoint() -> Self {
        Self {
            targets: targets::MIN.iter().zip(targets::MAX).map(|(min, max)| (min + max) / 2.0).collect(),
        }
    }

    pub fn encode(&self) -> Vec<u8> {
        let mut writer = Writer::new();
        writer.f32s(&self.targets, targets::LEN);
        writer.finish()
    }
}

struct Reader<'a> {
    rest: &'a [u8],
}

impl<'a> Reader<'a> {
    fn new(bytes: &'a [u8], kind: u8) -> Option<Self> {
        let header = bytes.get(..8)?;
        if &header[..3] != b"BSP" || header[3] != kind {
            return None;
        }
        if u32::from_le_bytes([header[4], header[5], header[6], header[7]]) != SCHEMA {
            return None;
        }
        Some(Self { rest: &bytes[8..] })
    }

    fn take(&mut self, len: usize) -> Option<&'a [u8]> {
        let size = self.rest.get(..4)?;
        let size = u32::from_le_bytes([size[0], size[1], size[2], size[3]]) as usize;
        if size != len {
            return None;
        }
        let body = self.rest.get(4..4 + size)?;
        self.rest = &self.rest[4 + size..];
        Some(body)
    }

    fn f32s(&mut self, count: usize) -> Option<Vec<f32>> {
        let body = self.take(count * 4)?;
        Some(body.chunks_exact(4).map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect())
    }

    fn u8s(&mut self, count: usize) -> Option<Vec<u8>> {
        self.take(count).map(<[u8]>::to_vec)
    }

    fn end(&self) -> bool {
        self.rest.is_empty()
    }
}

struct Writer {
    bytes: Vec<u8>,
}

impl Writer {
    fn new() -> Self {
        let mut bytes = b"BSPO".to_vec();
        bytes.extend_from_slice(&SCHEMA.to_le_bytes());
        Self { bytes }
    }

    fn f32s(&mut self, values: &[f32], count: usize) {
        self.bytes.extend_from_slice(&((count * 4) as u32).to_le_bytes());
        for index in 0..count {
            let value = values.get(index).copied().unwrap_or(f32::NAN);
            self.bytes.extend_from_slice(&value.to_le_bytes());
        }
    }

    fn u8s(&mut self, values: &[u8], count: usize) {
        self.bytes.extend_from_slice(&(count as u32).to_le_bytes());
        for index in 0..count {
            self.bytes.push(values.get(index).copied().unwrap_or(0));
        }
    }

    fn finish(self) -> Vec<u8> {
        self.bytes
    }
}
